<script setup lang="ts">
import { Link, router } from '@inertiajs/vue3';
import { computed, ref } from 'vue';

type OrderItem={id:number;product_id?:number|null;name:string;image:string;price:number;quantity:number;total?:number};
type OrderUser={id:number;name:string;email:string;phone?:string|null};
type Order={id:number;code:string;customer_name:string;customer_phone?:string|null;customer_email?:string|null;customer_address?:string|null;note?:string|null;payment:string;vat_invoice_requested:boolean;vat_company_name?:string|null;vat_tax_code?:string|null;vat_address?:string|null;vat_email?:string|null;vat_rate?:number|string;vat_amount?:number;paypal_order_id?:string|null;subtotal:number;shipping:number;total_shipping:number;total:number;status:string;created_at:string;items:OrderItem[];user?:OrderUser|null};
const props=defineProps<{orders:{data:Order[];current_page:number;last_page:number;total:number}}>();
const selectedOrder=ref<Order|null>(null); const approveTarget=ref<Order|null>(null); const approving=ref(false); const actionError=ref('');
const money=(n:number)=>new Intl.NumberFormat('vi-VN').format(Number(n||0))+' ₫';
const statusClass=(status:string)=>status==='Đã duyệt'?'is-approved':status==='Chờ xử lý'?'is-pending':status==='Hủy hàng'?'is-cancelled':'is-other';
const itemCount=computed(()=>selectedOrder.value?.items.reduce((sum,item)=>sum+Number(item.quantity||0),0)??0);
const paymentLabel=(payment:string)=>payment==='paypal-sandbox'?'PayPal Sandbox':payment==='paypal-demo'?'PayPal mô phỏng':'Thanh toán khi nhận hàng';
function openOrder(o:Order){selectedOrder.value=o} function closeOrder(){selectedOrder.value=null}
function requestApprove(o:Order){if(o.status!=='Chờ xử lý')return;actionError.value='';approveTarget.value=o}
function closeApprove(){if(!approving.value)approveTarget.value=null}
function confirmApprove(){const o=approveTarget.value;if(!o||approving.value)return;approving.value=true;router.patch(`/admin/orders/${o.id}/approve`,{}, {preserveScroll:true,onSuccess:()=>{approveTarget.value=null;selectedOrder.value=null},onError:()=>{actionError.value='Không thể duyệt đơn hàng. Vui lòng thử lại.'},onFinish:()=>{approving.value=false}})}
</script>
<template>
<div class="admin-page">
    <div class="admin-page-head"><div><div class="admin-kicker">ĐƠN HÀNG</div><h1>Duyệt đơn hàng</h1><p>Kiểm tra đầy đủ thông tin khách hàng, sản phẩm, thanh toán và hóa đơn trước khi duyệt.</p></div><div class="admin-chip"><i class="bi bi-inbox me-2"/>{{props.orders.total}} đơn</div></div>
    <div v-if="actionError" class="orders-action-error"><i class="bi bi-exclamation-circle"/>{{actionError}}<button type="button" @click="actionError=''" aria-label="Đóng"><i class="bi bi-x"/></button></div>
    <div class="orders-admin-panel"><div class="orders-admin-toolbar"><div><strong>Danh sách đơn hàng</strong><span>{{props.orders.total}} đơn trong hệ thống</span></div><div class="orders-admin-legend"><span><i class="dot pending"/> Chờ xử lý</span><span><i class="dot approved"/> Đã duyệt</span></div></div>
        <div class="table-responsive"><table class="table orders-admin-table align-middle"><thead><tr><th>Mã đơn</th><th>Khách hàng</th><th>Liên hệ</th><th>Ngày đặt</th><th>Số SP</th><th>Tổng tiền</th><th>Trạng thái</th><th class="text-end">Thao tác</th></tr></thead><tbody><tr v-for="o in props.orders.data" :key="o.id"><td><button type="button" class="order-code-btn" @click="openOrder(o)">{{o.code}}</button><small class="order-id">ID #{{o.id}}</small></td><td><strong>{{o.customer_name}}</strong><small>{{o.user?.email || o.customer_email || 'Chưa có Email'}}</small></td><td>{{o.customer_phone || o.user?.phone || '—'}}</td><td>{{new Date(o.created_at).toLocaleString('vi-VN')}}</td><td>{{o.items.reduce((sum,item)=>sum+Number(item.quantity||0),0)}}</td><td class="money-cell">{{money(o.total)}}</td><td><span :class="['order-status-badge',statusClass(o.status)]"><i class="bi bi-circle-fill"/>{{o.status}}</span></td><td class="text-end"><div class="order-table-actions"><button type="button" class="detail-btn" @click="openOrder(o)"><i class="bi bi-eye"/> Chi tiết</button><button v-if="o.status==='Chờ xử lý'" type="button" class="approve-btn" @click="requestApprove(o)"><i class="bi bi-check2"/> Duyệt</button><span v-else class="processed-text">Đã xử lý</span></div></td></tr><tr v-if="!props.orders.data.length"><td colspan="8" class="text-center py-5 text-secondary">Chưa có đơn hàng.</td></tr></tbody></table></div>
    </div>
    <div v-if="props.orders.last_page>1" class="d-flex justify-content-center gap-1 mt-3"><Link v-for="p in props.orders.last_page" :key="p" :href="`/admin/orders?page=${p}`" class="btn btn-sm" :class="p===props.orders.current_page?'btn-primary':'btn-light'">{{p}}</Link></div>
    <Teleport to="body"><div v-if="selectedOrder" class="order-detail-overlay" @click.self="closeOrder"><section class="order-detail-drawer" role="dialog" aria-modal="true"><header class="order-detail-head"><div><span class="drawer-kicker">CHI TIẾT ĐƠN HÀNG</span><h2>{{selectedOrder.code}}</h2><small>{{new Date(selectedOrder.created_at).toLocaleString('vi-VN')}}</small></div><div class="drawer-head-actions"><span :class="['order-status-badge',statusClass(selectedOrder.status)]"><i class="bi bi-circle-fill"/>{{selectedOrder.status}}</span><button type="button" class="drawer-close" @click="closeOrder"><i class="bi bi-x-lg"/></button></div></header><div class="order-detail-body"><section class="detail-section"><div class="detail-section-title"><i class="bi bi-person-vcard"/><div><strong>Thông tin khách hàng</strong><small>Thông tin tài khoản và lúc đặt hàng</small></div></div><div class="customer-grid"><div><span>Họ và tên</span><strong>{{selectedOrder.customer_name}}</strong></div><div><span>Email tài khoản</span><strong>{{selectedOrder.user?.email||'—'}}</strong></div><div><span>Số điện thoại</span><strong>{{selectedOrder.customer_phone||selectedOrder.user?.phone||'—'}}</strong></div><div><span>Email đặt hàng</span><strong>{{selectedOrder.customer_email||'—'}}</strong></div><div class="full"><span>Địa chỉ nhận hàng</span><strong>{{selectedOrder.customer_address||'—'}}</strong></div></div></section><section class="detail-section"><div class="detail-section-title"><i class="bi bi-box-seam"/><div><strong>Sản phẩm</strong><small>{{itemCount}} sản phẩm trong đơn</small></div></div><div class="detail-products"><article v-for="item in selectedOrder.items" :key="`${selectedOrder.id}-${item.id}`" class="detail-product"><div class="detail-product-image"><img :src="item.image" :alt="item.name"/></div><div class="detail-product-copy"><strong>{{item.name}}</strong><small>Đơn giá {{money(item.price)}} · Số lượng {{item.quantity}}</small></div><b>{{money(item.total??item.price*item.quantity)}}</b></article></div></section><section class="detail-columns"><div class="detail-section compact"><div class="detail-section-title"><i class="bi bi-credit-card"/><div><strong>Thanh toán</strong><small>Phương thức và tổng tiền</small></div></div><div class="info-list"><div><span>Phương thức</span><strong>{{paymentLabel(selectedOrder.payment)}}</strong></div><div><span>Tạm tính</span><strong>{{money(selectedOrder.subtotal)}}</strong></div><div><span>Phí vận chuyển</span><strong>{{money(selectedOrder.total_shipping)}}</strong></div><div v-if="selectedOrder.paypal_order_id"><span>Mã PayPal</span><strong>{{selectedOrder.paypal_order_id}}</strong></div><div><span>Tổng thanh toán</span><strong class="grand-total">{{money(selectedOrder.total)}}</strong></div></div></div><div class="detail-section compact"><div class="detail-section-title"><i class="bi bi-receipt-cutoff"/><div><strong>Hóa đơn VAT</strong><small>Thông tin xuất hóa đơn</small></div></div><div v-if="selectedOrder.vat_invoice_requested" class="info-list"><div><span>Doanh nghiệp / đơn vị</span><strong>{{selectedOrder.vat_company_name||'—'}}</strong></div><div><span>Mã số thuế</span><strong>{{selectedOrder.vat_tax_code||'—'}}</strong></div><div><span>Email</span><strong>{{selectedOrder.vat_email||'—'}}</strong></div><div><span>Địa chỉ</span><strong>{{selectedOrder.vat_address||'—'}}</strong></div><div><span>Thuế GTGT</span><strong>{{Number(selectedOrder.vat_rate||0).toFixed(0)}}% · {{money(Number(selectedOrder.vat_amount||0))}}</strong></div></div><div v-else class="no-vat"><i class="bi bi-file-earmark-x"/> Đơn hàng không yêu cầu xuất hóa đơn VAT.</div></div></section></div><footer class="order-detail-foot"><button type="button" class="secondary-detail-btn" @click="closeOrder">Đóng</button><button v-if="selectedOrder.status==='Chờ xử lý'" type="button" class="approve-detail-btn" @click="requestApprove(selectedOrder)"><i class="bi bi-check2-circle"/> Duyệt đơn hàng</button></footer></section></div></Teleport>
    <Teleport to="body"><div v-if="approveTarget" class="approve-overlay" @click.self="closeApprove"><section class="approve-dialog" role="dialog" aria-modal="true" aria-labelledby="approve-title"><div class="approve-icon"><i class="bi bi-check2-circle"/></div><div class="approve-copy"><span>XÁC NHẬN XỬ LÝ</span><h2 id="approve-title">Duyệt đơn hàng?</h2><p>Bạn đang xác nhận đơn <strong>#{{approveTarget.code}}</strong> của <strong>{{approveTarget.customer_name}}</strong>.</p><div class="approve-summary"><div><span>Tổng thanh toán</span><strong>{{money(approveTarget.total)}}</strong></div><div><span>Sản phẩm</span><strong>{{approveTarget.items.reduce((sum,item)=>sum+Number(item.quantity||0),0)}} sản phẩm</strong></div></div><div class="approve-warning"><i class="bi bi-info-circle-fill"/><span>Sau khi duyệt, đơn hàng sẽ chuyển sang <strong>Đã duyệt</strong> và hệ thống sẽ xử lý tồn kho theo quy trình.</span></div></div><footer><button type="button" class="approve-cancel" :disabled="approving" @click="closeApprove">Hủy</button><button type="button" class="approve-confirm" :disabled="approving" @click="confirmApprove"><i :class="['bi',approving?'bi-arrow-repeat spin':'bi-check-lg']"/>{{approving?'Đang duyệt...':'Xác nhận duyệt'}}</button></footer></section></div></Teleport>
</div>
</template>
